/**
 * scripts/lib/videsign-standard.mjs
 *
 * Reads the agent standard generated by videsign (`videsign-standard-source.json`,
 * pinned by the same SHA as the token sync). No font, colour, radius, duration or
 * glass value is hardcoded here — every value comes from that file's tokens.
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { resolve, dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { brandPreflightSection } from "./brand-v1.mjs";

const __dirname = dirname(fileURLToPath(import.meta.url));
// The consumer toolkit reads its pinned sources from `consumer/`, which is the
// directory that holds this `lib/`. It moved out of the site repository, where
// the pins sat at the repository root.
export const SITE_ROOT = resolve(__dirname, "..");
export const STANDARD_SOURCE = "videsign-standard-source.json";

/**
 * Returns the parsed raw tokens from videsign-tokens-source.json.
 * @param {string} [root]
 * @returns {Record<string, any>}
 */
export function getSourceTokens(root = SITE_ROOT) {
  const tokenFile = join(root, "videsign-tokens-source.json");
  if (!existsSync(tokenFile)) {
    throw new Error(`[videsign-standard] Missing tokens file: ${tokenFile}`);
  }
  return JSON.parse(readFileSync(tokenFile, "utf8"));
}

/**
 * Returns the videsign-generated agent standard (addendum §2).
 * @param {string} [root]
 * @returns {any}
 */
/** Neutral ADR-012 status. The pin stays; this replaces the upstream sentence. */
export const ADR_012_LOCAL_STATUS = "Accepted 2026-10-27. Used by the web app redesign.";

/** Date-only ADR-011 status. Items 7 and 10 only. */
export const ADR_011_LOCAL_STATUS =
  "Items 7 and 10 Accepted (2026-10-28). Items 1-6, 8 and 9 Proposed. Amends ADR-002.";

/**
 * Local overrides applied on every sync so a re-run cannot restore the
 * upstream ADR-012 sentence or an ADR-011 line that omits the date.
 * A later re-pin replaces these once the upstream text itself changes.
 * @param {string} text
 */
export function applyLocalStandardText(text) {
  const upstreamRedesign = [
    "Accepted for the ",
    "owner",
    "-",
    "approved",
    " Vi",
    "Web redesign (2026-10-27).",
  ].join("");
  const withoutRedesign = text.split(upstreamRedesign).join(ADR_012_LOCAL_STATUS);
  return withoutRedesign.replace(
    /("id": "ADR-011",\s*"title": "[^"]+",\s*"status": ")[^"]*(")/g,
    `$1${ADR_011_LOCAL_STATUS}$2`,
  );
}

export function getSourceStandard(root = SITE_ROOT) {
  const file = join(root, STANDARD_SOURCE);
  if (!existsSync(file)) {
    throw new Error(`[videsign-standard] Missing ${STANDARD_SOURCE}; sync from videsign dist/standard.json`);
  }
  return JSON.parse(applyLocalStandardText(readFileSync(file, "utf8")));
}

/**
 * Site-facing standard view derived entirely from the synced videsign standard.
 * @param {string} [root]
 * @returns {any}
 */
export function getViDesignStandard(root = SITE_ROOT) {
  const source = getSourceStandard(root);
  const tokens = source.tokens;
  const colors = tokens.colors;
  const typography = tokens.typography;
  const spacing = tokens.spacing;
  const size = tokens.size;
  const space = tokens.space;
  const transition = tokens.transition;
  const rules = source.rules;

  return {
    meta: {
      ...source.meta,
      syncedFrom: STANDARD_SOURCE,
      authorityFiles: [
        STANDARD_SOURCE,
        "videsign-tokens-source.json",
        "src/styles/videsign-tokens.css",
        "src/styles/videsign-glass.css",
      ],
    },
    source,
    colors: {
      tokens: {
        surfacePrimary: colors["surface-background-primary-base"],
        surfaceSecondary: colors["surface-background-secondary-base"],
        surfaceTertiary: colors["surface-background-tertiary-base"],
        accentViolet: colors["surface-accent-violet-base"],
        accentVioletHover: colors["surface-accent-violet-hover"],
        accentVioletActive: colors["surface-accent-violet-active"],
        textContentPrimary: colors["text-content-primary-base"],
        textContentSecondary: colors["text-content-secondary-base"],
        borderSeparatorPrimary: colors["border-separator-primary-base"],
        statusSuccess: colors["status-indicator-success-base"],
        statusWarning: colors["status-indicator-warning-base"],
        statusError: colors["status-indicator-error-base"],
        statusInfo: colors["status-indicator-info-base"],
        personaViolet: colors["persona-accent-violet-base"],
        personaWisteria: colors["persona-accent-wisteria-base"],
        personaXylia: colors["persona-accent-xylia-base"],
        personaYarrow: colors["persona-accent-yarrow-base"],
        personaZinnia: colors["persona-accent-zinnia-base"],
      },
      rules: [
        "Base surfaces must use solid colour tokens from the synced matrix.",
        "Cards and panels must not use drop shadows.",
        "Brand accent is reserved for key CTAs and focus outlines.",
      ],
    },
    typography: {
      families: {
        sans: typography["typography-family-sans-base"],
        mono: typography["typography-family-mono-base"],
      },
      weights: {
        regular: typography["typography-weight-regular-base"],
        medium: typography["typography-weight-medium-base"],
        semibold: typography["typography-weight-semibold-base"],
        bold: typography["typography-weight-bold-base"],
      },
      tracking: {
        tight: typography["typography-tracking-tight-base"],
        normal: typography["typography-tracking-normal-base"],
        wide: typography["typography-tracking-wide-base"],
        widest: typography["typography-tracking-widest-base"],
      },
      leading: {
        none: typography["typography-leading-none-base"],
        tight: typography["typography-leading-tight-base"],
        normal: typography["typography-leading-normal-base"],
      },
      usage: {
        mono: "Navigation, metadata labels, status badges, code, and table headers.",
        sans: "Page titles, section headers, ledes, body text, and long-form prose.",
      },
      scale: typography,
      sentenceCase: rules.typography.sentenceCase,
      banUppercaseUtility: rules.typography.banUppercaseUtility,
      ceiling: {
        size4xl: typography["typography-size-4xl-base"],
        size5xl: typography["typography-size-5xl-base"],
        hero: typography["typography-fluid-hero-base"],
        rule: "No public heading may exceed the 5xl ceiling except the sanctioned hero token (videsign ADR-005).",
      },
    },
    geometry: {
      radius: {
        standardLayout: spacing["layout-radius-standard-base"],
        controlsAndInputs: spacing["layout-radius-control-base"],
        glass: spacing["layout-radius-glass-base"],
        pill: spacing["layout-radius-full-base"],
        bezel: spacing["layout-padding-bezel-base"],
      },
      rules: [
        "Layout cards use the standard radius; controls use the control radius.",
        "Glass shells use the glass radius with bezel padding and a concentric core.",
        "Generic 32px radii are forbidden.",
      ],
    },
    motion: {
      durations: rules.motion.durationsMs,
      easing: rules.motion.easing,
      animateOnly: rules.motion.animateOnly,
    },
    spacing: {
      rhythmBasePx: rules.spacing.rhythmBasePx,
      pageGutter: space["rhythm-page-gutter-base"],
      sectionY: space["rhythm-section-y-base"],
      macroWhitespace: space["rhythm-macro-base"],
      scale: space,
    },
    glass: rules.glass,
    conversation: rules.conversation ?? null,
    instrument: rules.instrument ?? null,
    layoutAndContainment: {
      contentMaxWidth: size["layout-width-content-base"],
      rules: [
        "Site content shell is bounded to the content-width token.",
        "Text and card content must remain inside layout bounds at all times.",
        "Inline stylesheets in Astro config are disabled (inlineStylesheets: 'never').",
      ],
    },
    accessibility: {
      touchTargetFloor: size["action-min-default"],
      contrastFloorText: rules.accessibility.contrastFloorText,
      personaVioletAccentTextSurfaces: rules.accessibility.personaVioletAccentTextSurfaces,
      rules: [
        "Interactive targets meet the action-min touch floor.",
        "Descriptive alt text is mandatory on all <img> elements; decorative images use alt=\"\".",
        "Violet persona accent text sits on the primary surface only.",
      ],
    },
    transition,
    adrs: source.adrs,
    negativeBoundaries: [
      {
        rule: "ENFORCE_SENTENCE_CASE",
        description: "All section headers, card titles, button labels, and body text must be in sentence case.",
        prohibited: "Title Case; Tailwind uppercase utility; text-transform: uppercase on labels.",
      },
      {
        rule: "BAN_EMOJIS",
        description: "Explicitly forbid decorative emojis anywhere in markup, templates, or component copy.",
        prohibited: "Decorative unicode emojis.",
      },
      {
        rule: "BAN_ARBITRARY_TAILWIND",
        description: "Never generate arbitrary Tailwind values. Always map to design system tokens.",
        prohibited: "Arbitrary classes like w-[15px], p-[13px], rounded-[32px], text-[var(--accent)].",
      },
      {
        rule: "BAN_32PX_RADII",
        description: "Aggressively forbid the 32px web radii frequently hallucinated by models.",
        prohibited: "border-radius: 32px, rounded-2xl at 2rem.",
      },
      {
        rule: "BAN_EXTRANEOUS_SHADOWS",
        description: "Standard cards, panels, and buttons must not use drop shadows. Crystal glass carries its own tokenized shadow.",
        prohibited: "box-shadow / shadow-lg on flat panels.",
      },
      {
        rule: "RESTRICT_GLASSMORPHISM",
        description: "Crystal glass only on controls and the evidence lens; shell+core for text-bearing glass.",
        prohibited: "backdrop-blur-* / bg-white/*; glass on paragraphs, cards, sidebars; glass inside glass.",
      },
      {
        rule: "BAN_BILLBOARD_HEADINGS",
        description: "No font-size may exceed the 5xl ceiling except the sanctioned hero token.",
        prohibited: "Billboard maxima written outside the hero token.",
      },
      {
        rule: "BAN_RAW_DESIGN_VALUES",
        description: "Colours, clamps, durations, spacing lengths, weight, tracking, leading and radius come from synced tokens.",
        prohibited: "Raw hex, clamp(), ms, rem lengths, font-weight, letter-spacing, line-height, border-radius outside generated files and the alias layer (baseline may only shrink).",
      },
      {
        rule: "BAN_UPPERCASE_TRANSFORMS",
        description: "Eyebrows and labels are Geist Mono in sentence case with a tracking token.",
        prohibited: "text-transform: uppercase; Tailwind uppercase.",
      },
    ],
  };
}

/**
 * Markdown prompt injection derived from the synced standard (no hardcoded values).
 * @param {string} [root]
 * @returns {string}
 */
export function getViDesignStandardMarkdown(root = SITE_ROOT) {
  const std = getViDesignStandard(root);
  const c = std.colors.tokens;
  const g = std.geometry.radius;
  const t = std.typography;

  return `# ViDesign Standard (Nocturne Museum) — Forced-Retrieval Truth Layer

> **Authority**: ${std.meta.canonicalProvenance} | Version ${std.meta.version}
> Synced from \`${STANDARD_SOURCE}\`. All UI generation MUST comply.

## 1. Semantic Token Palette
- **Surface Primary**: \`${c.surfacePrimary}\`
- **Surface Secondary**: \`${c.surfaceSecondary}\`
- **Surface Tertiary**: \`${c.surfaceTertiary}\`
- **Accent**: \`${c.accentViolet}\`
- **Text Primary**: \`${c.textContentPrimary}\`
- **Text Secondary**: \`${c.textContentSecondary}\`
- **Border**: \`${c.borderSeparatorPrimary}\`
- **Pre-sync**: the surface, text, and border lines above are the pre-sync sheet, not the rendered field neutrals. The accent line is the synced CTA and focus value.

## 2. Geometry & Touch Targets
- **Layout radius**: \`${g.standardLayout}\`
- **Control radius**: \`${g.controlsAndInputs}\`
- **Glass shell / bezel**: \`${g.glass}\` / \`${g.bezel}\`
- **Touch target floor**: \`${std.accessibility.touchTargetFloor}\`
- **Content max width**: \`${std.layoutAndContainment.contentMaxWidth}\`

## 3. Typography & Hierarchy
- **Sans**: \`${t.families.sans}\`
- **Mono**: \`${t.families.mono}\`
- **Sentence case**: ${t.sentenceCase}; ban \`uppercase\` utility: ${t.banUppercaseUtility}
- **Display weight / tracking**: \`${t.weights.semibold}\` / \`${t.tracking.tight}\`
- **Ceiling**: 5xl \`${t.ceiling.size5xl}\`; hero \`${t.ceiling.hero}\`

## 4. Glass (ADR-006)
- Material: ${std.glass.material}; text-bearing: ${std.glass.textBearing}
- Scope: ${std.glass.scope.join("; ")}
- Ban legacy: ${std.glass.banLegacyUtilities.join(", ")}
- Legibility floor: ${std.glass.legibilityFloor}:1

## 5. Spacing rhythm (ADR-009)
- Base: ${std.spacing.rhythmBasePx}px
- Page gutter / section Y / macro: \`${std.spacing.pageGutter}\` / \`${std.spacing.sectionY}\` / \`${std.spacing.macroWhitespace}\`

## 6. Motion (ADR-008)
- Durations: ${Object.entries(std.motion.durations).map(([k, v]) => `${k}=${v}`).join(", ")}
- Animate only: ${std.motion.animateOnly.join(", ")}

## 7. Strict Negative Boundaries
${std.negativeBoundaries.map((/** @type {{ rule: string, description: string }} */ b, /** @type {number} */ i) => `${i + 1}. **${b.rule}**: ${b.description}`).join("\n")}
${conversationSection(std.conversation)}${instrumentSection(std.instrument)}
${brandPreflightSection()}
`;
}

/**
 * Conversation surface (videsign ADR-016): what every AI chat surface shows.
 * @param {any} c
 * @returns {string}
 */
function conversationSection(c) {
  if (!c) return "";
  return `
## 8. Conversation surface (${c.adr})
- Applies to: ${c.appliesTo.join("; ")}
- At rest: ${c.atRest.join("; ")}
- Header (one row, as tall as the avatar): first line ${c.header.firstLine.join(", ")}; second line ${c.header.secondLine.join(", ")}; not printed: ${c.header.notPrinted.join(", ")}
- Narrow: ${c.header.narrow}
- Seat dots: ${c.seatDots.seats.join(", ")}; \`${c.seatDots.pressedState}\`; hit area at least \`${c.seatDots.minTarget}\` in both dimensions; no printed names
- Guide reply: ${c.messages.guide}. Visitor turn: ${c.messages.visitor}
- Speaker marker: ${c.messages.speakerMarker}
- Message actions: ${c.messages.actions}
- Provenance: ${c.messages.provenance}
- Starters: at most ${c.starters.max}, one source, gone after the first turn. Follow-ups: at most ${c.followUps.max}, latest reply only
- Composer: one field with send inside; ${c.composer.keys}
- Disclosure: ${c.disclosure.linesAtRest} line at rest; detail ${c.disclosure.detail}; before the first turn ${c.disclosure.beforeFirstTurn}
- States: ${c.states.join(", ")}
- Motion: opens on ${c.motion.open}; a turn enters on ${c.motion.turnEnter}; the only loop is the ${c.motion.onlyLoop}
`;
}

/**
 * Explorable instrument (videsign ADR-017): interactive panels in articles and proofs.
 * @param {any} i
 * @returns {string}
 */
function instrumentSection(i) {
  if (!i) return "";
  return `
## 9. Explorable instrument (${i.adr})
- Every control changes the readout or the diagram, or it is removed
- Opens with: ${i.opensWith.join("; ")}
- Anatomy: ${i.anatomy.join(", ")}; ${i.surface}
- Controls: boolean = ${i.controls.boolean}; number = ${i.controls.number}; presets = ${i.controls.presets}
- Banned: ${i.controls.banned.join(", ")}
- Diagram: lines \`${i.diagram.line}\`; current = ${i.diagram.current}; blocked = \`${i.diagram.blocked}\` with a text label; labels never overlap
- Receipt: ${i.receipt.form}; aria-live ${i.receipt.ariaLive}
- A fixture-driven instrument says so once; seat colours only where the five seats appear together
`;
}

export const TARGET_AGENT_FILES = [
  ".opencode/agents/vidox-site.md",
  ".opencode/agents/site-experience.md",
];

export const PREFLIGHT_START = "<!-- VIDESIGN_PREFLIGHT_START -->";
export const PREFLIGHT_END = "<!-- VIDESIGN_PREFLIGHT_END -->";

/**
 * Injects the ViDesign Standard markdown into agent configs.
 * @param {string} [root]
 * @param {string[]} [agentFiles]
 * @returns {Array<{ file: string, updated: boolean }>}
 */
export function injectViDesignIntoAgentConfigs(root = SITE_ROOT, agentFiles = TARGET_AGENT_FILES) {
  const markdown = getViDesignStandardMarkdown(root);
  const injectionBlock = `${PREFLIGHT_START}\n${markdown.trim()}\n${PREFLIGHT_END}`;
  const results = [];

  for (const relFile of agentFiles) {
    const fullPath = join(root, relFile);
    if (!existsSync(fullPath)) {
      results.push({ file: relFile, updated: false });
      continue;
    }

    const content = readFileSync(fullPath, "utf8");
    let newContent;

    if (content.includes(PREFLIGHT_START) && content.includes(PREFLIGHT_END)) {
      const startIndex = content.indexOf(PREFLIGHT_START);
      const endIndex = content.indexOf(PREFLIGHT_END) + PREFLIGHT_END.length;
      newContent = content.slice(0, startIndex) + injectionBlock + content.slice(endIndex);
    } else {
      newContent = content.trimEnd() + "\n\n" + injectionBlock + "\n";
    }

    if (newContent !== content) {
      writeFileSync(fullPath, newContent, "utf8");
      results.push({ file: relFile, updated: true });
    } else {
      results.push({ file: relFile, updated: false });
    }
  }

  return results;
}

/**
 * Writes docs/design/videsign-standard.* from the synced source and injects agents.
 * @param {string} [root]
 */
export function syncViDesignStandardFiles(root = SITE_ROOT) {
  const designDir = join(root, "docs/design");
  const jsonPath = join(designDir, "videsign-standard.json");
  const mdPath = join(designDir, "videsign-standard.md");
  const sourcePath = join(root, STANDARD_SOURCE);
  if (existsSync(sourcePath)) {
    const raw = readFileSync(sourcePath, "utf8");
    const next = applyLocalStandardText(raw);
    if (next !== raw) writeFileSync(sourcePath, next.endsWith("\n") ? next : `${next}\n`, "utf8");
  }

  const standard = getViDesignStandard(root);
  const markdown = getViDesignStandardMarkdown(root);

  writeFileSync(jsonPath, JSON.stringify(standard, null, 2) + "\n", "utf8");
  writeFileSync(mdPath, markdown, "utf8");

  const agentInjections = injectViDesignIntoAgentConfigs(root);

  return { jsonPath, mdPath, agentInjections };
}
